from pathlib import Path
import json
r=Path(__file__).resolve().parents[1]
w=json.loads((r/'pc/weights.json').read_text()); f=json.loads((r/'android/app/src/main/assets/fixtures.json').read_text())
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'none'"><title>Offline Shapes</title><style>body{font:17px system-ui;background:#eef3f4;color:#16383c;margin:0;padding:24px}main{max-width:620px;margin:auto;background:white;padding:28px;border-radius:20px}h1{margin:0 0 12px}canvas{display:block;width:min(100%,384px);height:auto;touch-action:none;margin:24px auto;border:1px solid #ccd5d8}button{font:inherit;padding:10px 15px;border:0;border-radius:8px;margin:4px;background:#dcebee;color:#16383c;cursor:pointer}output{display:block;white-space:pre-line;min-height:80px;margin-top:20px}small{display:block;margin-top:20px;line-height:1.6}</style><main><h1>Offline Shapes</h1><p>A small trained neural network. Load a sample or paint a centered, filled shape on the grid.</p><canvas id="grid" width="384" height="384" aria-label="16 by 16 editable shape grid"></canvas><div id="samples"></div><button id="clear">Clear</button><button id="eraser">Eraser off</button><button id="classify">Classify</button><button id="test">Self test</button><output id="result"></output><small>This self contained page uses the exported neural network weights in JavaScript. The Android app uses the ONNX file and native ONNX Runtime. Neither requires a server. Synthetic demonstration only; scores are not calibrated confidence.</small></main><script>
const W=__WEIGHTS__, F=__FIXTURES__, names=['Circle','Square','Triangle'];
function forward(x){const hidden=W['net.0.weight'].map((row,i)=>Math.max(0,row.reduce((a,w,j)=>a+w*x[j],W['net.0.bias'][i])));return W['net.2.weight'].map((row,i)=>row.reduce((a,w,j)=>a+w*hidden[j],W['net.2.bias'][i]));}
function selfTest(){let max=0;for(const f of F){const out=forward(f.pixels);if(out.indexOf(Math.max(...out))!==f.label)throw Error('Wrong fixture class');out.forEach((v,k)=>{max=Math.max(max,Math.abs(v-f.logits[k]));});}if(max>.001)throw Error('Parity error '+max);return 'PASS · 3 of 3 fixtures. Maximum logit error '+max.toExponential(2);}
let pixels=Array(256).fill(0),erase=false,down=false;
const canvas=document.getElementById('grid'),ctx=canvas.getContext('2d'),result=document.getElementById('result');
function draw(){pixels.forEach((p,i)=>{ctx.fillStyle=p?'#235c60':'#eef3f4';ctx.fillRect((i%16)*24+1,Math.floor(i/16)*24+1,22,22);});}
function classify(){if(!pixels.some(v=>v)){result.textContent='Empty grid. Choose a sample or paint a filled shape.';return;}const start=performance.now(),out=forward(pixels),b=out.indexOf(Math.max(...out)),total=out.reduce((s,v)=>s+Math.exp(v-out[b]),0);result.textContent=names[b]+' · model score '+(100/total).toFixed(1)+'%\\nInference '+(performance.now()-start).toFixed(3)+' ms';}
function paint(e){const b=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-b.left)/b.width*16),y=Math.floor((e.clientY-b.top)/b.height*16);if(x>=0&&x<16&&y>=0&&y<16)pixels[y*16+x]=erase?0:1;draw();}
canvas.onpointerdown=e=>{down=true;canvas.setPointerCapture(e.pointerId);paint(e);};canvas.onpointermove=e=>{if(down)paint(e);};canvas.onpointerup=()=>{down=false;classify();};canvas.onpointercancel=()=>down=false;
names.forEach((name,i)=>{const b=document.createElement('button');b.textContent=name;b.onclick=()=>{pixels=F[i].pixels.slice();draw();classify();};document.getElementById('samples').append(b);});
document.getElementById('clear').onclick=()=>{pixels.fill(0);draw();classify();};document.getElementById('eraser').onclick=e=>{erase=!erase;e.target.textContent='Eraser '+(erase?'on':'off');};document.getElementById('classify').onclick=classify;document.getElementById('test').onclick=()=>result.textContent=selfTest();draw();result.textContent=selfTest();
</script></html>'''
(r/'Offline_Shapes.html').write_text(html.replace('__WEIGHTS__',json.dumps(w)).replace('__FIXTURES__',json.dumps(f)))
reference = 'const W='+json.dumps(w)+'; const F='+json.dumps(f)+';\nfunction forward(x)'+html.split('function forward(x)')[1].split('let pixels=')[0]+'\nconsole.log(selfTest());'
(r/'pc/reference_test.js').write_text(reference)
